/**
 * Descriptive statistics over an array of numbers.
 *
 * One fold, three readers. The semantics are unchanged, including `mode`'s tie-break:
 * the first value encountered with the highest count wins, because `>` (not `>=`) keeps
 * insertion order decisive.
 */

/**
 * @template A, T
 * @param {T[]} values
 * @param {(accumulator: A, value: T) => A} step
 * @param {A} seed
 * @returns {A}
 */
function fold(values, step, seed) {
  let accumulator = seed;
  for (const value of values) {
    accumulator = step(accumulator, value);
  }
  return accumulator;
}

/**
 * @param {number[]} values
 * @returns {number}
 */
export function mean(values) {
  return fold(values, (total, value) => total + value, 0) / values.length;
}

/**
 * @param {number[]} values
 * @returns {number}
 */
export function median(values) {
  const sorted = [...values].sort((left, right) => left - right);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle];
}

/**
 * @param {number[]} values
 * @returns {number}
 */
export function mode(values) {
  const counts = fold(values, (tally, value) => tally.set(value, (tally.get(value) ?? 0) + 1), new Map());

  let best = values[0];
  let bestCount = 0;
  for (const [value, count] of counts) {
    if (count > bestCount) {
      best = value;
      bestCount = count;
    }
  }
  return best;
}
